('advanced-native-1162', '["phrase"]'::jsonb, '{"advanced-native-1162-v1-audio":{"type":"mc","answers":["The booked reader became unavailable, and unexpected letters arrived."],"options":["The reader arrived as booked, while the expected box failed to arrive.","The booked reader became unavailable, and unexpected letters arrived.","The team had planned both the reader’s absence and the extra box as regular programme items.","The programme was completed before any new information appeared."]},"advanced-native-1162-v2-reply":{"type":"mc","answers":["Our available reader and the material we could include had both changed unexpectedly.","The project threw us two curveballs that needed fresh decisions.","We needed to consider the new letters as well as the missing reader.","The original plan no longer covered all the information and people now involved."],"options":["Our available reader and the material we could include had both changed unexpectedly.","The project threw us two curveballs that needed fresh decisions.","We needed to consider the new letters as well as the missing reader.","The original plan no longer covered all the information and people now involved."]},"advanced-native-1162-v1-scene":{"type":"mc","answers":["The demonstration is a known challenge, not by itself an unexpected curveball the workshop has thrown them."],"options":["The account says the demonstration was added only after they arrived.","The demonstration is a known challenge, not by itself an unexpected curveball the workshop has thrown them.","A demanding task is necessarily a surprise even when it was explained and prepared for."]},"advanced-native-1162-v1-contrast":{"type":"mc","answers":["Someone deliberately caused the difficulty to defeat the group."],"options":["Something unexpected complicated the situation.","Someone deliberately caused the difficulty to defeat the group.","The context can identify what had been expected instead."]},"advanced-native-1162-v1-branch":{"type":"mc","an