('advanced-native-1163', '["phrase"]'::jsonb, '{"advanced-native-1163-v1-audio":{"type":"mc","answers":["Patience, practical help and asking for a pause instead of blaming a newcomer."],"options":["The newest member was found responsible and told to leave before reconstruction began.","The partner refused to pause and insisted that the actors continue without cues.","Patience, practical help and asking for a pause instead of blaming a newcomer.","The partner proved she could complete every role alone without help."]},"advanced-native-1163-v2-reply":{"type":"mc","answers":["I saw patience and practical cooperation under pressure.","It showed me what she was made of through the way she treated the others.","She recognised when the group needed a pause and made room for it.","She helped people recover the cues without turning the problem into blame."],"options":["I saw patience and practical cooperation under pressure.","It showed me what she was made of through the way she treated the others.","She recognised when the group needed a pause and made room for it.","She helped people recover the cues without turning the problem into blame."]},"advanced-native-1163-v1-scene":{"type":"mc","answers":["Asking for a first step does not by itself settle what he is made of or erase his continued attempt."],"options":["Asking for a first step does not by itself settle what he is made of or erase his continued attempt.","Only refusing help would provide any evidence of resolve.","The unfinished answer shows he has already chosen to abandon the remaining work."]},"advanced-native-1163-v1-contrast":{"type":"mc","answers":["One incident has established every aspect of her character permanently."],"options":["The speaker should explain which observed actions support the judgement.","The speaker interprets her response as revealing some character or ability.","One incident has established every aspect of her character permanently."]},"advanced-native-1163-v1-branch":{"type":"mc","answe